 {board.money.style!=='studio'&&<><Field label="Bill heading"><select value={board.money.headingMode||(board.money.personalize?'bank':'original')} onChange={e=>changeMoney('headingMode',e.target.value)}><option value="original">Original MONOPOLY</option><option value="board">Use board name</option><option value="custom">Custom wording</option><option value="bank">Use bank name</option></select></Field>{board.money.headingMode==='custom'&&<Field label="Custom bill heading"><TextInput value={board.money.headingText||''} maxLength={48} onChange={v=>changeMoney('headingText',v)}/></Field>}{(board.money.headingMode||(board.money.personalize?'bank':'original'))!=='original'&&<div className="bill-heading-color"><BillFontControls value={billHeading(board).value} onNotice={setNotice}/><GroupColorControl label="Bill heading text" color={board.money.headingColor||'#000000'} onChange={v=>changeMoney('headingColor',v)}/><button className="text-button" onClick={()=>changeMoney('headingColor','#000000')}>Black bill heading</button><small>Black &amp; white bills always print the heading in black. Turn that option off to apply a heading color.</small></div>}</>}
